from datetime import datetime
from typing import Dict, List, Optional, Tuple

class Scheduler:
    def __init__(self) -> None:
        self.appointments: Dict[int, Dict[str, any]] = {}
        self.next_id = 1
        # Track patient's upcoming appointments for constraint #1
        self.patient_appointments: Dict[str, List[int]] = {}
        # Track doctor's appointments for constraint #3
        self.doctor_appointments: Dict[str, List[int]] = {}

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        # Constraint #4: Booking an appointment that starts before `now` raises ValueError
        if start < now:
            raise ValueError("Appointment cannot start before current time")

        # Constraint #1: A patient can have at most one upcoming appointment
        if patient in self.patient_appointments:
            # Check if patient has any upcoming appointments (start > now)
            for appt_id in self.patient_appointments[patient]:
                appt = self.appointments[appt_id]
                if appt["start"] > now and not appt.get("cancelled", False):
                    raise ValueError("Patient already has an upcoming appointment")

        # Constraint #3: Booking an appointment that overlaps another appointment of the same doctor
        if doctor in self.doctor_appointments:
            for appt_id in self.doctor_appointments[doctor]:
                appt = self.appointments[appt_id]
                if appt.get("cancelled", False):
                    continue
                # Check for overlap: two intervals [a,b] and [c,d] overlap if a < d and c < b
                # Since touching is allowed (one ends exactly when another starts), we use strict inequalities
                if start < appt["end"] and appt["start"] < end:
                    raise ValueError("Doctor is not available during this time period")

        # Create new appointment
        appointment_id = self.next_id
        self.next_id += 1

        self.appointments[appointment_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "cancelled": False
        }

        # Update patient's appointment list
        if patient not in self.patient_appointments:
            self.patient_appointments[patient] = []
        self.patient_appointments[patient].append(appointment_id)

        # Update doctor's appointment list
        if doctor not in self.doctor_appointments:
            self.doctor_appointments[doctor] = []
        self.doctor_appointments[doctor].append(appointment_id)

        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self.appointments:
            raise ValueError("Appointment does not exist")

        appointment = self.appointments[appointment_id]
        if appointment.get("cancelled", False):
            return  # Already cancelled

        # Can only cancel future appointments (start > now)
        if appointment["start"] <= now:
            raise ValueError("Cannot cancel past or current appointment")

        appointment["cancelled"] = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        # If doctor has no appointments, they're free
        if doctor not in self.doctor_appointments:
            return True

        # Check all appointments for this doctor
        for appt_id in self.doctor_appointments[doctor]:
            appt = self.appointments[appt_id]
            if appt.get("cancelled", False):
                continue
            # Check for overlap: two intervals [a,b] and [c,d] overlap if a < d and c < b
            # Since touching is allowed, we use strict inequalities
            if start < appt["end"] and appt["start"] < end:
                return False

        return True
